1: //! DJI `.txt` Gimbal Telemetry Decoder (Record Type 3).
2: //!
3: //! Decodes 3-axis gimbal orientation (pitch, roll, yaw), mechanical/software limit
4: //! bitmasks, motor stall detection, stabilization modes, and horizon-relative tilt.
5: 
6: use byteorder::{ByteOrder, LittleEndian};
7: 
8: use crate::error::{FlightReaderError, Result};
9: 
10: /// Telemetry record type identifier for Gimbal packets.
11: pub const RECORD_TYPE: u8 = 3;
12: 
13: /// Minimum allowable payload length (bytes 0..6: pitch, roll, yaw, bitmask).
14: pub const MIN_PAYLOAD_LEN: usize = 7;
15: 
16: /// Extended payload length including horizon-relative tilt (bytes 20..21).
17: pub const EXTENDED_PAYLOAD_LEN: usize = 22;
18: 
19: /// Gimbal stabilization and tracking operational mode.
20: #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
21: #[repr(u8)]
22: pub enum GimbalMode {
23:     /// Gimbal orientation is uncoupled from aircraft yaw.
24:     Free = 0,
25:     /// Gimbal yaw follows aircraft heading, roll follows RC roll channel (First-Person View).
26:     Fpv = 1,
27:     /// Gimbal yaw smoothly follows aircraft nose heading ("Follow Yaw").
28:     Follow = 2,
29:     /// Unmapped or vendor-reserved mode code.
30:     Unknown(u8),
31: }
32: 
33: impl GimbalMode {
34:     /// Creates a `GimbalMode` from raw 2-bit value (0..=3).
35:     #[inline]
36:     pub const fn from_bits(bits: u8) -> Self {
37:         match bits & 0x03 {
38:             0 => Self::Free,
39:             1 => Self::Fpv,
40:             2 => Self::Follow,
41:             other => Self::Unknown(other),
42:         }
43:     }
44: 
45:     /// Returns the descriptive display label matching C# `ClsLog.GimbalModeText`.
46:     #[inline]
47:     pub const fn as_str(&self) -> &'static str {
48:         match self {
49:             Self::Free => "Free",
50:             Self::Fpv => "FPV",
51:             Self::Follow => "Follow Yaw",
52:             Self::Unknown(_) => "Unknown",
53:         }
54:     }
55: }
