36: /// Converts raw deci-Kelvin integer ($0.1\text{ K}$) to degrees Celsius (°C).
37: ///
38: /// Returns [`SENTINEL_UNINITIALIZED`] if `raw <= 0` (indicating uninitialized sensor).
39: #[inline]
40: pub fn deci_kelvin_to_celsius(raw: i16) -> f64 {
41:     if raw <= 0 {
42:         SENTINEL_UNINITIALIZED
43:     } else {
44:         (raw as f64 / 10.0) - 273.15
45:     }
46: }
47: 
48: /// Converts degrees Celsius (°C) back to raw deci-Kelvin ($0.1\text{ K}$) for testing.
49: #[inline]
50: pub fn celsius_to_deci_kelvin(celsius: f64) -> i16 {
51:     ((celsius + 273.15) * 10.0).round() as i16
52: }
