54: /// Normalizes raw battery current in milliamperes (mA) to Amperes (A).
55: ///
56: /// Implements two's complement inversion when $val > 40.0\text{ A}$ per `CalculateBatteryCurrent`.
57: #[inline]
58: pub fn raw_current_to_amperes(raw: u16) -> f64 {
59:     let val = raw as f64 / 1000.0;
60:     if val > 40.0 {
61:         (65536.0 - raw as f64) / 1000.0
62:     } else {
63:         val
64:     }
65: }
