94:     /// Parses an Energy Summary packet from a raw payload slice.
95:     pub fn parse(payload: &[u8]) -> Result<Self> {
96:         if payload.len() < VARIANT_A_MIN_LEN {
97:             return Err(FlightReaderError::TruncatedRecord {
98:                 expected: VARIANT_A_MIN_LEN,
99:                 available: payload.len(),
100:             });
101:         }
102: 
103:         let relative_capacity = payload[0];
104:         let voltage = LittleEndian::read_u16(&payload[1..3]) as f64 / 1000.0;
105:         let current_capacity_mah = LittleEndian::read_u16(&payload[3..5]);
106:         let full_capacity_mah = LittleEndian::read_u16(&payload[5..7]);
107:         let cell_count = payload[7];
108:         let temperature_celsius = deci_kelvin_to_celsius(LittleEndian::read_i16(&payload[8..10]));
109: 
110:         let current_draw_amperes = if payload.len() >= 16 {
111:             Some(raw_current_to_amperes(LittleEndian::read_u16(
112:                 &payload[14..16],
113:             )))
114:         } else if payload.len() >= 12 {
115:             Some(raw_current_to_amperes(LittleEndian::read_u16(
116:                 &payload[10..12],
117:             )))
118:         } else {
119:             None
120:         };
121: 
122:         Ok(Self {
123:             relative_capacity,
124:             voltage,
125:             current_capacity_mah,
126:             full_capacity_mah,
